import React, { useState, useContext, useEffect } from 'react';
import { Form, Button, Card, Table, Badge, Row, Col, InputGroup } from 'react-bootstrap';
import api from '../services/api';
import { toast } from 'react-toastify';
import { AuthContext } from '../context/AuthContext';

const SalesForm = () => {
  const [amount, setAmount] = useState('');
  const [status, setStatus] = useState('pending');
  const [mySales, setMySales] = useState([]);
  const { user } = useContext(AuthContext);

  const fetchMySales = async () => {
    try {
      const { data } = await api.get('/sales/my');
      setMySales(data);
    } catch (err) {
      toast.error('Failed to load my sales');
    }
  };

  useEffect(() => {
    fetchMySales();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!amount || amount <= 0) {
      toast.error('Please enter a valid sale amount');
      return;
    }
    try {
      await api.post('/sales', { amount: parseFloat(amount), status });
      toast.success('🎉 Sale recorded & broadcasted to live analytics dashboard!');
      setAmount('');
      setStatus('pending');
      fetchMySales();
    } catch (err) {
      toast.error(err.response?.data?.message || 'Failed to record sale');
    }
  };

  const totalAmount = mySales.reduce((acc, curr) => acc + (curr.amount || 0), 0);

  return (
    <div>
      <div className="mb-4">
        <h3 className="fw-bold mb-1">Staff Workspace</h3>
        <p className="text-muted small mb-0">Record your sales entries. All submissions update central admin graphs live.</p>
      </div>

      <Row className="g-3 mb-4">
        <Col md={6}>
          <div className="stat-card shadow-sm">
            <div className="stat-icon success">💰</div>
            <div>
              <div className="text-muted small fw-semibold text-uppercase">Your Total Recorded Volume</div>
              <h3 className="fw-extrabold mb-0">${totalAmount.toLocaleString(undefined, { minimumFractionDigits: 2 })}</h3>
            </div>
          </div>
        </Col>
        <Col md={6}>
          <div className="stat-card shadow-sm">
            <div className="stat-icon primary">📊</div>
            <div>
              <div className="text-muted small fw-semibold text-uppercase">Your Total Transactions</div>
              <h3 className="fw-extrabold mb-0">{mySales.length} Submissions</h3>
            </div>
          </div>
        </Col>
      </Row>

      <Row className="g-4">
        <Col lg={5}>
          <Card className="p-4 border-0">
            <h5 className="fw-bold mb-3">Add New Sale</h5>
            <Form onSubmit={handleSubmit}>
              <Form.Group className="mb-3">
                <Form.Label className="small fw-semibold">Sale Status</Form.Label>
                <Form.Select
                  required
                  value={status}
                  onChange={e => setStatus(e.target.value)}
                >
                  <option value="pending">Pending</option>
                  <option value="won">Won</option>
                  <option value="lost">Lost</option>
                </Form.Select>
              </Form.Group>
              <Form.Group className="mb-3">
                <Form.Label className="small fw-semibold">Sale Amount</Form.Label>
                <InputGroup>
                  <InputGroup.Text className="bg-body border-end-0 fw-bold">$</InputGroup.Text>
                  <Form.Control
                    type="number"
                    min="0.01"
                    step="0.01"
                    required
                    value={amount}
                    onChange={e => setAmount(e.target.value)}
                    placeholder="1500.00"
                    className="border-start-0"
                    style={{ borderRadius: '0 10px 10px 0' }}
                  />
                </InputGroup>
              </Form.Group>
              <Button type="submit" className="btn-success-gradient w-100 py-3 mt-2">
                Submit Sale Record →
              </Button>
            </Form>
          </Card>
        </Col>

        <Col lg={7}>
          <Card className="p-4 border-0">
            <div className="d-flex justify-content-between align-items-center mb-3">
              <h5 className="fw-bold mb-0">Your Submissions</h5>
              <Badge bg="success" className="px-3 py-2 rounded-pill">Total: ${totalAmount.toFixed(2)}</Badge>
            </div>
            <Table responsive className="custom-table mb-0">
              <thead>
                <tr>
                  <th>#</th>
                  <th>Amount</th>
                  <th>Status</th>
                  <th>Timestamp</th>
                </tr>
              </thead>
              <tbody>
                {mySales.length === 0 ? (
                  <tr>
                    <td colSpan="4" className="text-center py-4 text-muted">No sales recorded yet. Submit your first sale on the left!</td>
                  </tr>
                ) : (
                  mySales.map((s, idx) => (
                    <tr key={s._id || idx}>
                      <td>{idx + 1}</td>
                      <td className="fw-bold text-success">${Number(s.amount).toFixed(2)}</td>
                      <td className="text-capitalize">{s.status}</td>
                      <td className="small text-muted">{new Date(s.createdAt).toLocaleString()}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </Table>
          </Card>
        </Col>
      </Row>
    </div>
  );
};

export default SalesForm;
